**Answer: (A).**
', status = 'READY', answer_type = 'MCQ', nat_min = NULL, nat_max = NULL, difficulty = 2, answer_status = 'OFFICIAL_KEY', content_key = 'gate2016-s1-q30', origin = 'PYQ', updated_at = now() WHERE id = qid;
