DO $ppimport$
DECLARE qid int; tid int; subj int;
BEGIN
  SELECT id INTO qid FROM question WHERE content_key = 'gate2016-s1-q53';
  IF qid IS NULL THEN
    SELECT qs.question_id INTO qid FROM question_source qs JOIN source s ON s.id = qs.source_id
      JOIN question x ON x.id = qs.question_id
      WHERE (s.code, qs.q_no) IN (('GATE-2016', 'S1-Q53')) AND x.content_key IS NULL ORDER BY qs.question_id LIMIT 1;
  END IF;
  IF qid IS NULL THEN
    IF tid IS NULL THEN RAISE EXCEPTION 'paper question gate2016-s1-q53: no skeleton row, give a topic'; END IF;
    INSERT INTO question(subject_id, topic_id, summary, stem_md, solution_md, status, answer_type, nat_min, nat_max,
                         difficulty, answer_status, content_key, origin)
    VALUES (subj, tid, 'A dc voltage with ripple is given by $v(t) = [100 + 10\sin(\omega t) - 5\sin(3\omega t)]$ volts. Measurements of this voltage $v(t)$, made by moving-coil...', 'A dc voltage with ripple is given by $v(t) = [100 + 10\sin(\omega t) - 5\sin(3\omega t)]$ volts. Measurements of this voltage $v(t)$, made by
moving-coil and moving-iron voltmeters, show readings of $V_1$ and $V_2$ respectively. The value of $V_2 - V_1$, in volts, is _________.
', '**Idea used:** a moving-coil (PMMC) meter reads the **average** (dc) value; a moving-iron meter reads the **rms** value.

1. $V_1$ = average $= 100$ V (sine terms average to zero).
2. $V_2$ = rms $= \sqrt{100^2 + \dfrac{10^2}{2} + \dfrac{5^2}{2}} = \sqrt{10\,000 + 50 + 12.5} = \sqrt{10\,062.5}$.
3. $\sqrt{10\,062.5} \approx 100.31$ V.
4. $V_2 - V_1 \approx 0.31$ V.

**Without a calculator:** for a small addition $\Delta$ to $100^2$, $\sqrt{100^2 + \Delta} \approx 100 + \dfrac{\Delta}{200}$.
Here $\Delta = 62.5$, so the difference is $62.5 / 200 \approx 0.31$. Option C is the rms of the ripple alone
($\sqrt{62.5} \approx 7.9$); option D forgets the $\tfrac12$ in the sine rms.

**Answer: about 0.31 V.**
', 'READY', 'NAT', 0.3, 0.33, 2, 'OFFICIAL_KEY', 'gate2016-s1-q53', 'PYQ') RETURNING id INTO qid;
  ELSE
    UPDATE question SET topic_id = COALESCE(tid, topic_id), subject_id = COALESCE(subj, subject_id), summary = COALESCE(NULLIF(summary, ''), 'A dc voltage with ripple is given by $v(t) = [100 + 10\sin(\omega t) - 5\sin(3\omega t)]$ volts. Measurements of this voltage $v(t)$, made by moving-coil...'), stem_md = 'A dc voltage with ripple is given by $v(t) = [100 + 10\sin(\omega t) - 5\sin(3\omega t)]$ volts. Measurements of this voltage $v(t)$, made by
moving-coil and moving-iron voltmeters, show readings of $V_1$ and $V_2$ respectively. The value of $V_2 - V_1$, in volts, is _________.
', solution_md = '**Idea used:** a moving-coil (PMMC) meter reads the **average** (dc) value; a moving-iron meter reads the **rms** value.

1. $V_1$ = average $= 100$ V (sine terms average to zero).
2. $V_2$ = rms $= \sqrt{100^2 + \dfrac{10^2}{2} + \dfrac{5^2}{2}} = \sqrt{10\,000 + 50 + 12.5} = \sqrt{10\,062.5}$.
3. $\sqrt{10\,062.5} \approx 100.31$ V.
4. $V_2 - V_1 \approx 0.31$ V.

**Without a calculator:** for a small addition $\Delta$ to $100^2$, $\sqrt{100^2 + \Delta} \approx 100 + \dfrac{\Delta}{200}$.
Here $\Delta = 62.5$, so the difference is $62.5 / 200 \approx 0.31$. Option C is the rms of the ripple alone
($\sqrt{62.5} \approx 7.9$); option D forgets the $\tfrac12$ in the sine rms.

**Answer: about 0.31 V.**
', status = 'READY', answer_type = 'NAT', nat_min = 0.3, nat_max = 0.33, difficulty = 2, answer_status = 'OFFICIAL_KEY', content_key = 'gate2016-s1-q53', origin = 'PYQ', updated_at = now() WHERE id = qid;
  END IF;
  INSERT INTO question_source(source_id, q_no, question_id, marks, is_primary) VALUES ((SELECT id FROM source WHERE code = 'GATE-2016'), 'S1-Q53', qid, 2, TRUE) ON CONFLICT (source_id, q_no) DO UPDATE SET question_id = EXCLUDED.question_id, marks = EXCLUDED.marks, is_primary = EXCLUDED.is_primary;
  DELETE FROM question_option WHERE question_id = qid AND label NOT IN ('A', 'B', 'C', 'D');
  INSERT INTO question_option(question_id, label, body_md, is_correct) VALUES (qid, 'A', '0.31', TRUE) ON CONFLICT (question_id, label) DO UPDATE SET body_md = EXCLUDED.body_md, is_correct = EXCLUDED.is_correct;
  INSERT INTO question_option(question_id, label, body_md, is_correct) VALUES (qid, 'B', '0', FALSE) ON CONFLICT (question_id, label) DO UPDATE SET body_md = EXCLUDED.body_md, is_correct = EXCLUDED.is_correct;
  INSERT INTO question_option(question_id, label, body_md, is_correct) VALUES (qid, 'C', '7.9', FALSE) ON CONFLICT (question_id, label) DO UPDATE SET body_md = EXCLUDED.body_md, is_correct = EXCLUDED.is_correct;
  INSERT INTO question_option(question_id, label, body_md, is_correct) VALUES (qid, 'D', '0.62', FALSE) ON CONFLICT (question_id, label) DO UPDATE SET body_md = EXCLUDED.body_md, is_correct = EXCLUDED.is_correct;
  DELETE FROM question_mcq_option WHERE question_id = qid;
END $ppimport$;
